def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    environment = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 1)
    grid_height = observation.get("grid_height", 1)

    # Helper function to get moves towards a target
    def move_towards(target_x, target_y):
        dx = 0 if target_x == sx else (1 if target_x > sx else -1)
        dy = 0 if target_y == sy else (1 if target_y > sy else -1)
        return [dx, dy]

    # Defensive extraction of relevant data
    resources = observation.get("resources") or []
    unclaimed_cells = observation.get("unclaimed_cells") or []
    opponent_territory = observation.get("opponent_territory") or []
    self_role = observation.get("self_role", "neutral")

    # Pursuit and evasion
    if environment == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_towards(ox, oy)
        else:
            corners = [
                (0, 0),
                (0, grid_height - 1),
                (grid_width - 1, 0),
                (grid_width - 1, grid_height - 1),
            ]
            target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
            return move_towards(target[0], target[1])

    # Territory control
    if environment == "territory_control":
        targets = unclaimed_cells or opponent_territory
        if targets:
            best_target = min(targets, key=lambda t: abs(t[0] - sx) + abs(t[1] - sy))
            return move_towards(best_target[0], best_target[1])
        else:
            return [0,0]

    # Resource collection
    if resources:
        best_resource = min(resources, key=lambda r: abs(r[0]-sx)+abs(r[1]-sy))
        return move_towards(best_resource[0], best_resource[1])
    else:
        # Fallback: move towards opponent to prevent stalling
        return move_towards(ox, oy)

